#!/usr/bin/env bun
/**
 * Regenerate the frozen RPC channel inventory.
 *
 * ```bash
 * bun run scripts/ipc-inventory.ts            # rewrite the block
 * bun run scripts/ipc-inventory.ts --check    # fail if it is stale
 * ```
 *
 * ## Why this file has to exist
 *
 * `apps/electron/src/shared/__tests__/ipc-channels.test.ts` carries a generated
 * block introduced by the sentence «Auto-generated by scripts/ipc-inventory.ts —
 * DO NOT edit by hand», and **that script was never in the repo**. So the only
 * way to satisfy the comment was to edit by hand the exact list it forbids
 * editing by hand. Three `feat/models-fetch` channels drifted in silence until a
 * release-gate `bun test` caught them, and the repair (`e16df6563`) was itself
 * hand-written.
 *
 * A comment naming a tool that does not exist is worse than no comment: it
 * tells a reader the drift is handled.
 *
 * ## What it does NOT do, deliberately
 *
 * It does not touch the two sibling registration contracts. They catch a
 * different drift class — a channel REGISTERED by a handler but never declared
 * in `RPC_CHANNELS` — which this inventory cannot see, because it reads the
 * declaration and nothing else. Folding them together would replace two
 * independent checks with one blind spot.
 *
 * The inventory is a WIRE-FORMAT contract: renaming a channel string breaks
 * every client built against the old one, so the intended workflow is that a
 * deliberate rename regenerates this block in the same commit, and an
 * accidental one fails `--check` in CI.
 *
 * ## Why the audit is exported rather than inlined
 *
 * `--check` lived only inside `bun run validate:ci`, and CI runs
 * `typecheck:all`, `lint`, `bun test` and `test:shared:all` — never that
 * aggregate. Worse, `validate:ci` begins with `validate:dev`, which ends in
 * `test:doc-tools`, the Python job CI itself disabled for want of runner
 * mirrors; measured 2026-08-25 it fails locally too (12 failures / 2 errors,
 * no PyPI mirror), so the four checks chained after it are unreachable even
 * for a developer who runs the aggregate by hand. Two channels
 * (`workspace:importClaudePreview`, `workspace:importClaudeApply`) duly
 * drifted in `e815ad274` and nothing said so.
 *
 * So the audit is a pure function and `scripts/ipc-inventory.test.ts` is its
 * enforcing reader, because `bun test` is what CI actually runs — the same
 * disposition `check-coverage-map.ts` took, and for the same reason. The
 * marker check in particular had NO reader of any kind: damage the BEGIN/END
 * pair and the frozen list keeps passing while the generator that maintains it
 * can no longer run.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

import { RPC_CHANNELS } from '../apps/electron/src/shared/types.ts'

const TEST_FILE = join(import.meta.dir, '..', 'apps', 'electron', 'src', 'shared', '__tests__', 'ipc-channels.test.ts')
const BEGIN = '// Auto-generated by scripts/ipc-inventory.ts — DO NOT edit by hand.'
const END = '// End auto-generated'

/**
 * The second header line, added 2026-09-07 (`P6.687`) because the first one is
 * not true enough to act on.
 *
 * «DO NOT edit by hand» says the edit is unwanted; it does not say what happens
 * to it. What happens is that the whole block is re-rendered from `RPC_CHANNELS`,
 * so a hand-written line between the markers is DELETED WITHOUT A WORD on the
 * next run — one such comment was written and is gone, which is how this row was
 * found. A reader who believes a comment survives will write one again.
 *
 * Preserving them was the alternative and is rejected under the standing rule to
 * write as little code as possible: a comment inside a sorted, wholly re-rendered
 * list has no stable anchor to be re-attached to, and the machinery to guess one
 * would be larger than the block it protects. Saying so, and COUNTING what is
 * dropped, is the smallest honest thing — and the count is what turns "your edit
 * is gone" from a discovery into a line of output.
 */
export const NOTICE = '// Everything between these markers is REWRITTEN WHOLE from RPC_CHANNELS, comments included: '
  + 'a hand-written line here is discarded (and counted) on the next run. Put notes ABOVE the line above.'

/**
 * A line this generator can emit. Anything else between the markers is a hand
 * edit, and that is the whole discrimination this row turns on: comparing the
 * old block to the new one instead would report a REMOVED CHANNEL as a lost hand
 * edit, which is a different event with a different remedy.
 */
const GENERATED_SHAPE =
  /^(?:|\s*'[^']*',|const EXPECTED_CHANNELS: string\[\] = \[|\]|const EXPECTED_COUNT = EXPECTED_CHANNELS\.length)$/

/** The hand-written lines inside the block, which a rewrite will discard. */
export function discardedLines(source: string): string[] {
  const begin = source.indexOf(BEGIN)
  const end = source.indexOf(END)
  if (begin === -1 || end === -1 || end < begin) return []
  return source
    .slice(begin + BEGIN.length, end)
    .split('\n')
    .filter(line => line !== NOTICE && !GENERATED_SHAPE.test(line))
}

/** Every string leaf, in declaration order — the same walk the test performs. */
export function flattenValues(obj: Record<string, unknown>): string[] {
  return Object.values(obj).flatMap(value =>
    typeof value === 'string' ? [value]
      : typeof value === 'object' && value !== null ? flattenValues(value as Record<string, unknown>)
      : [],
  )
}

export function renderBlock(channels: readonly string[]): string {
  const lines = channels.map(channel => `  '${channel}',`).join('\n')
  return `${BEGIN}\n${NOTICE}\nconst EXPECTED_CHANNELS: string[] = [\n${lines}\n]\n\nconst EXPECTED_COUNT = EXPECTED_CHANNELS.length\n${END}`
}

/** Why a run cannot proceed, or `'ok'`. Each value is a distinct real defect. */
export type MarkerState = 'ok' | 'missing' | 'out-of-order'

export interface InventoryAudit {
  /** Wire names declared more than once — deduped, in first-seen order. */
  readonly duplicates: readonly string[]
  /** Whether the generated block's delimiters are usable. */
  readonly markers: MarkerState
  /** The frozen block disagrees with the declaration. */
  readonly stale: boolean
  /**
   * Hand-written lines inside the block that a rewrite will DELETE (`P6.687`).
   * Reported rather than preserved, and reported by the CALLER rather than
   * silently — the marker line says the edit is unwanted, this says it is gone.
   */
  readonly discarded: readonly string[]
  /**
   * The block predates `NOTICE` and will gain it on the next rewrite.
   *
   * DELIBERATELY NOT `stale`, and this is the one judgement in the row. The
   * frozen list is a WIRE-FORMAT contract and `stale` is what says it has
   * drifted; the notice is documentation OF that block. Folding the notice into
   * `stale` would have turned an unrelated green gate red in every tree that had
   * not yet regenerated — including CI, on a clean checkout, for a comment. It is
   * reported on every run instead, and the writer treats it as a reason to write,
   * so it lands on the next run rather than waiting for a channel to change.
   */
  readonly noticeMissing: boolean
  /** What the generator would write; absent when it cannot run. */
  readonly next?: string
}

/**
 * The whole decision, as data. Callers report; this function never writes,
 * never exits and never logs, so a test can ask it about a fixture.
 */
export function auditInventory(source: string, channels: readonly string[]): InventoryAudit {
  // A duplicate is a real defect — two declarations answering to one wire name —
  // and it must be reported rather than silently deduped into a passing list.
  const duplicates = [...new Set(channels.filter((value, index) => channels.indexOf(value) !== index))]
  if (duplicates.length > 0) return { duplicates, markers: 'ok', stale: false, discarded: [], noticeMissing: false }

  const begin = source.indexOf(BEGIN)
  const end = source.indexOf(END)
  // Both halves are checked because either alone leaves the generator unable to
  // run while the frozen list it maintains keeps passing.
  if (begin === -1 || end === -1) return { duplicates, markers: 'missing', stale: false, discarded: [], noticeMissing: false }
  if (end < begin) return { duplicates, markers: 'out-of-order', stale: false, discarded: [], noticeMissing: false }

  const discarded = discardedLines(source)
  const next = `${source.slice(0, begin)}${renderBlock([...channels].sort())}${source.slice(end + END.length)}`
  // Staleness is asked of the block AS IF it already carried the notice, so a
  // block that differs only by that line is not reported as drifted. See
  // `noticeMissing`.
  const noticeMissing = !source.includes(NOTICE)
  const compared = noticeMissing ? source.replace(BEGIN, `${BEGIN}\n${NOTICE}`) : source
  return { duplicates, markers: 'ok', stale: next !== compared, next, discarded, noticeMissing }
}

function main(): number {
  const channels = flattenValues(RPC_CHANNELS as unknown as Record<string, unknown>)
  const source = readFileSync(TEST_FILE, 'utf8')
  const audit = auditInventory(source, channels)

  if (audit.duplicates.length > 0) {
    console.error(`duplicate channel strings in RPC_CHANNELS: ${audit.duplicates.join(', ')}`)
    return 2
  }
  if (audit.markers !== 'ok') {
    console.error(
      `markers ${audit.markers} in ${TEST_FILE}; expected ${JSON.stringify(BEGIN)} `
      + `then ${JSON.stringify(END)}, in that order.`,
    )
    return 2
  }

  // Said on EVERY run, before the outcome, and by both modes — a rewrite is
  // where the loss happens and `--check` is where it can still be prevented.
  if (audit.discarded.length > 0) {
    console.error(
      `ipc-inventory: ${audit.discarded.length} hand-written line(s) inside the generated block will be `
      + 'DISCARDED by a rewrite (the block is re-rendered whole from RPC_CHANNELS). Move anything worth '
      + `keeping ABOVE the ${JSON.stringify(BEGIN)} line:`,
    )
    for (const line of audit.discarded) console.error(`    ${line}`)
  }

  if (audit.noticeMissing) {
    console.log(
      'ipc-inventory: the generated block predates the "rewritten whole" notice and will gain it on the '
      + 'next rewrite. Not counted as stale — the frozen list is the contract, the notice documents it.',
    )
  }

  if (process.argv.includes('--check')) {
    if (!audit.stale) {
      console.log(`ipc-inventory: up to date (${channels.length} channels)`)
      return 0
    }
    console.error(
      `ipc-inventory: ${TEST_FILE} is STALE.\n`
      + `RPC_CHANNELS declares ${channels.length} channel strings and the frozen list does not match.\n`
      + 'Run `bun run scripts/ipc-inventory.ts` and commit the result in the same commit as the channel change.',
    )
    return 1
  }

  // `noticeMissing` is a reason to WRITE even when the list agrees, so the notice
  // arrives on the next run of the generator rather than on the next channel change.
  if (!audit.stale && !audit.noticeMissing) {
    console.log(`ipc-inventory: no change (${channels.length} channels)`)
    return 0
  }
  writeFileSync(TEST_FILE, audit.next as string, 'utf8')
  console.log(
    `ipc-inventory: rewrote ${channels.length} channels`
    + (audit.discarded.length > 0 ? `, discarding ${audit.discarded.length} hand-written line(s)` : ''),
  )
  return 0
}

// Importing this file must not run it: the reader below imports the audit, and
// a module that rewrites a source file at import time would rewrite it during
// `bun test`.
if (import.meta.main) process.exit(main())
